 1→import { unpinFromIpfs } from '../lib/api/ipfs';
 2→import { useQuotaStore } from '../stores/quota.store';
 3→
 4→/**
 5→ * Deletes a file by unpinning from IPFS and updating quota.
 6→ *
 7→ * In v2 metadata, the caller must first resolve the file's per-IPNS metadata
 8→ * to obtain the CID before calling this function. The folder metadata only
 9→ * contains a FilePointer with fileMetaIpnsName, not the CID directly.
10→ *
11→ * @param cid - CID of the file to delete
12→ * @param sizeBytes - Size of the file (for quota update)
13→ */
14→export async function deleteFile(cid: string, sizeBytes: number): Promise<void> {
15→  // 1. Unpin from IPFS via backend
16→  await unpinFromIpfs(cid);
17→
18→  // 2. Update local quota
19→  const quotaStore = useQuotaStore.getState();
20→  quotaStore.removeUsage(sizeBytes);
21→
22→  // TODO: Phase 14 should add TEE unenrollment for orphaned file IPNS records.
23→  // Currently, the file IPNS record and its TEE enrollment are left to expire
24→  // naturally (24h IPNS record lifetime, TEE republishing will stop after
25→  // the enrollment entry is cleaned up). This is acceptable for v1 because:
26→  // - No data leakage (the encrypted metadata CID becomes unreachable)
27→  // - Storage cost is minimal (IPNS records are small)
28→  // - The republish service has capacity warnings at 1000+ records
29→}
30→
31→/**
32→ * Deletes multiple files by unpinning from IPFS.
33→ *
34→ * @param files - Array of { cid, size } objects
35→ */
36→export async function deleteFiles(
37→  files: Array<{ cid: string; size: number }>
38→): Promise<{ succeeded: string[]; failed: string[] }> {
39→  const succeeded: string[] = [];
40→  const failed: string[] = [];
41→
42→  for (const file of files) {
43→    try {
44→      await deleteFile(file.cid, file.size);
45→      succeeded.push(file.cid);
46→    } catch (error) {
47→      console.error(`Failed to delete ${file.cid}:`, error);
48→      failed.push(file.cid);
49→    }
50→  }
51→
52→  return { succeeded, failed };
53→}
