 1→import { create } from 'zustand';
 2→import { vaultApi, QuotaResponse } from '../lib/api/vault';
 3→
 4→type QuotaState = {
 5→  usedBytes: number;
 6→  limitBytes: number;
 7→  remainingBytes: number;
 8→  loading: boolean;
 9→  error: string | null;
10→
11→  fetchQuota: () => Promise<void>;
12→  removeUsage: (bytes: number) => void;
13→  canUpload: (bytes: number) => boolean;
14→};
15→
16→export const useQuotaStore = create<QuotaState>((set, get) => ({
17→  usedBytes: 0,
18→  limitBytes: 500 * 1024 * 1024, // 500 MiB
19→  remainingBytes: 500 * 1024 * 1024,
20→  loading: false,
21→  error: null,
22→
23→  fetchQuota: async () => {
24→    set({ loading: true, error: null });
25→    try {
26→      const quota: QuotaResponse = await vaultApi.getQuota();
27→      set({
28→        usedBytes: quota.usedBytes,
29→        limitBytes: quota.limitBytes,
30→        remainingBytes: quota.remainingBytes,
31→        loading: false,
32→      });
33→    } catch {
34→      set({ error: 'Failed to fetch quota', loading: false });
35→    }
36→  },
37→
38→  removeUsage: (bytes) =>
39→    set((state) => ({
40→      usedBytes: Math.max(0, state.usedBytes - bytes),
41→      remainingBytes: Math.min(state.limitBytes, state.remainingBytes + bytes),
42→    })),
43→
44→  canUpload: (bytes) => {
45→    const { remainingBytes } = get();
46→    return bytes <= remainingBytes;
47→  },
48→}));
