 930→/**
 931→ * Fetch and decrypt folder metadata from IPFS.
 932→ *
 933→ * Used for sync operations when remote IPNS resolves to a different CID.
 934→ * Fetches the encrypted metadata blob from IPFS and decrypts it with the folder key.
 935→ * @param cid - IPFS CID of the encrypted metadata blob
 936→ * @param folderKey - Decrypted AES-256 folder key
 937→ * @returns Decrypted folder metadata (v2)
 938→ * @throws Error if fetch or decryption fails
 939→ */
 940→export async function fetchAndDecryptMetadata(
 941→  cid: string,
 942→  folderKey: Uint8Array
 943→): Promise<FolderMetadata> {
 944→  // 1. Fetch encrypted metadata blob from IPFS
 945→  const encryptedBytes = await fetchFromIpfs(cid);
 946→
 947→  // 2. Parse as JSON to get EncryptedFolderMetadata (contains iv and data fields)
 948→  const encryptedJson = new TextDecoder().decode(encryptedBytes);
 949→  const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
 950→
 951→  // 3. Decrypt using folder key
 952→  const metadata = await decryptFolderMetadata(encrypted, folderKey);
 953→
 954→  return metadata;
 955→}
 956→
 957→// ---------------------------------------------------------------------------
 958→// Lazy key rotation integration
 959→// ---------------------------------------------------------------------------
 960→
 961→/**
 962→ * Check if a folder has pending key rotations and execute rotation if needed.
 963→ *
 964→ * Called before folder modifications to ensure the folderKey is rotated
 965→ * after a share has been revoked. This implements lazy rotation: the key
 966→ * is only rotated when the sharer next modifies the folder.
 967→ *
 968→ * If rotation occurs:
 969→ * 1. A new random folderKey is generated
 970→ * 2. The folder metadata is re-encrypted with the new key
 971→ * 3. The new key is re-wrapped for all remaining (non-revoked) share recipients
 972→ * 4. Revoked share records are hard-deleted
 973→ * 5. The new folderKey is returned for the caller to use
 974→ *
 975→ * If no rotation is needed, the original folderKey is returned unchanged.
 976→ *
 977→ * NOTE: The parent folder's folderKeyEncrypted for this child is NOT updated
 978→ * here. The parent metadata update (re-wrapping the new folderKey with the
 979→ * owner's public key) is handled by the caller since it has access to the
 980→ * parent folder context. The caller must update the parent folder's children
 981→ * array with the new folderKeyEncrypted for this folder entry.
 982→ *
 983→ * @param params.folderNode - The folder node being modified
 984→ * @returns The folderKey to use (new if rotated, original if not)
 985→ */
 986→export async function checkAndRotateIfNeeded(params: {
 987→  folderNode: FolderNode;
 988→}): Promise<{ folderKey: Uint8Array; rotated: boolean }> {
 989→  // Lazy import to avoid circular dependency at module evaluation time
 990→  const { checkPendingRotation, executeLazyRotation } = await import('./share.service');
 991→
 992→  const { folderNode } = params;
 993→
 994→  // 1. Check if any revoked shares are pending rotation for this folder
 995→  const hasPending = await checkPendingRotation(folderNode.ipnsName);
 996→  if (!hasPending) {
 997→    return { folderKey: folderNode.folderKey, rotated: false };
 998→  }
 999→
1000→  const auth = useAuthStore.getState();
1001→  if (!auth.vaultKeypair) {
1002→    // Cannot rotate without owner's keypair -- skip rotation, use existing key
1003→    console.warn('[share] Cannot perform lazy rotation: no vault keypair available');
1004→    return { folderKey: folderNode.folderKey, rotated: false };
1005→  }
1006→
1007→  // 2. Execute lazy rotation: generates new key, re-wraps for remaining recipients,
1008→  //    hard-deletes revoked share records
1009→  const { newFolderKey } = await executeLazyRotation({
1010→    folderIpnsName: folderNode.ipnsName,
1011→    oldFolderKey: folderNode.folderKey,
1012→    ownerPublicKey: auth.vaultKeypair.publicKey,
1013→  });
1014→
1015→  // 3. Re-encrypt folder metadata with the new key
1016→  //    Resolve current IPNS -> fetch encrypted metadata -> decrypt with old key -> re-encrypt with new key
1017→  const resolved = await resolveIpnsRecord(folderNode.ipnsName);
1018→  if (!resolved) {
1019→    // IPNS resolution failed after rotation was committed (share keys already re-wrapped,
1020→    // revoked shares hard-deleted). Metadata is still encrypted with the old key.
1021→    // Throw so the caller doesn't proceed with the new key in an inconsistent state.
1022→    console.error(
1023→      `[share] IPNS resolution failed after lazy rotation for ${folderNode.ipnsName}. ` +
1024→        'Share keys were updated but metadata was not re-encrypted.'
1025→    );
1026→    throw new Error(
1027→      'Key rotation failed: could not resolve folder IPNS for metadata re-encryption'
1028→    );
1029→  }
1030→
1031→  const currentMetadata = await fetchAndDecryptMetadata(resolved.cid, folderNode.folderKey);
1032→
1033→  // Re-encrypt and publish with new key.
1034→  // If another device published concurrently we get a 409 conflict.
1035→  // The share key rotation (re-wrap + delete) was already committed, so
1036→  // we return the new key and defer the metadata re-encryption to the next
1037→  // sync cycle, when the caller will re-read fresh state and retry.
1038→  try {
1039→    await updateFolderMetadata({
1040→      folderId: folderNode.id,
1041→      children: currentMetadata.children ?? [],
1042→      folderKey: newFolderKey,
1043→      ipnsPrivateKey: folderNode.ipnsPrivateKey,
1044→      ipnsName: folderNode.ipnsName,
1045→      sequenceNumber: resolved.sequenceNumber,
1046→    });
1047→  } catch (err) {
1048→    if (isConflictError(err)) {
1049→      // Key rotation committed (shares re-wrapped, revoked shares deleted).
1050→      // Metadata publish failed due to concurrent modification. On next sync
1051→      // the folder will be re-read with fresh state; checkAndRotateIfNeeded
1052→      // will detect the still-pending rotation and retry re-encryption then.
1053→      console.warn(
1054→        `[share] Conflict during lazy rotation metadata publish for ${folderNode.ipnsName}. ` +
1055→          'Will retry on next sync cycle.'
1056→      );
1057→      // Return the new key so the caller can use it for the file being uploaded.
1058→      return { folderKey: newFolderKey, rotated: true };
1059→    }
1060→    throw err; // Re-throw non-conflict errors
1061→  }
1062→
1063→  // 4. Re-wrap new folderKey in parent metadata
1064→  //    The parent needs its child's folderKeyEncrypted updated.
1065→  //    This is done by the caller since they have access to the parent folder.
1066→  //    We just return the new key and the rotated flag.
1067→
1068→  return { folderKey: newFolderKey, rotated: true };
1069→}
1070→

 1→/**
 2→ * @cipherbox/crypto - Registry IPNS Key Derivation
 3→ *
 4→ * Derives a deterministic Ed25519 IPNS keypair for the device registry
 5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
 6→ *
 7→ * Derivation path:
 8→ *   secp256k1 privateKey (32 bytes)
 9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-device-registry-ipns-v1")
10→ *     -> 32-byte Ed25519 seed
11→ *     -> Ed25519 keypair
12→ *     -> IPNS name (k51...)
13→ *
14→ * This enables any authenticated session with the user's privateKey
15→ * to discover the registry IPNS name without backend assistance.
16→ */
17→
18→import { deriveKey } from '../keys/derive';
19→import * as ed from '@noble/ed25519';
20→import { deriveIpnsName } from '../ipns/derive-name';
21→import { CryptoError } from '../types';
22→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
23→
24→const REGISTRY_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
25→const REGISTRY_HKDF_INFO = new TextEncoder().encode('cipherbox-device-registry-ipns-v1');
26→
27→/**
28→ * Derive the deterministic Ed25519 IPNS keypair for the device registry.
29→ *
30→ * Given the same secp256k1 privateKey, this always produces the same
31→ * IPNS name, enabling discovery from any device.
32→ *
33→ * @param userPrivateKey - 32-byte secp256k1 private key
34→ * @returns Ed25519 keypair and IPNS name for the registry
35→ * @throws CryptoError if the private key is not 32 bytes
36→ */
37→export async function deriveRegistryIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
38→  privateKey: Uint8Array;
39→  publicKey: Uint8Array;
40→  ipnsName: string;
41→}> {
42→  // Validate input key length
43→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
44→    throw new CryptoError('Invalid private key size for registry derivation', 'INVALID_KEY_SIZE');
45→  }
46→
47→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
48→  const ed25519Seed = await deriveKey({
49→    inputKey: userPrivateKey,
50→    salt: REGISTRY_HKDF_SALT,
51→    info: REGISTRY_HKDF_INFO,
52→    outputLength: 32,
53→  });
54→
55→  // 2. Derive Ed25519 public key from seed (deterministic)
56→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
57→
58→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
59→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
60→
61→  return {
62→    privateKey: ed25519Seed,
63→    publicKey: ed25519PublicKey,
64→    ipnsName,
65→  };
66→}
67→

  1→/**
  2→ * Search Index Service
  3→ *
  4→ * Manages a client-side search index for file and folder names using MiniSearch.
  5→ * The index is encrypted with AES-256-GCM (key derived via HKDF from the user's
  6→ * vault private key) before persisting to IndexedDB for zero-knowledge on-disk storage.
  7→ *
  8→ * This is a pure TypeScript service with no React dependencies.
  9→ */
 10→
 11→import MiniSearch from 'minisearch';
 12→import type { FolderNode } from '../stores/folder.store';
 13→
 14→// ---------------------------------------------------------------------------
 15→// Types
 16→// ---------------------------------------------------------------------------
 17→
 18→/** A document stored in the MiniSearch index. */
 19→type SearchDocument = {
 20→  /** Unique key: `${folderId}:${childId}` (avoids collisions across folders) */
 21→  id: string;
 22→  /** File or folder name (what users search for) */
 23→  name: string;
 24→  /** Whether this is a file or folder */
 25→  type: 'file' | 'folder';
 26→  /** Breadcrumb path like "My Vault / Documents / Reports" */
 27→  parentPath: string;
 28→  /** Folder ID for navigation on result click */
 29→  parentFolderId: string;
 30→  /** Timestamp for display in results (Unix ms) */
 31→  modifiedAt: number;
 32→};
 33→
 34→/** A search result returned by the service. */
 35→export type SearchResult = {
 36→  id: string;
 37→  name: string;
 38→  type: 'file' | 'folder';
 39→  parentPath: string;
 40→  parentFolderId: string;
 41→  modifiedAt: number;
 42→  /** MiniSearch relevance score (higher = better match) */
 43→  score: number;
 44→  /** Match info from MiniSearch, maps field name to matching terms */
 45→  match: Record<string, string[]>;
 46→};
 47→
 48→// ---------------------------------------------------------------------------
 49→// MiniSearch options (shared between constructor and loadJSON)
 50→// ---------------------------------------------------------------------------
 51→
 52→const MINISEARCH_OPTIONS = {
 53→  fields: ['name'],
 54→  storeFields: ['name', 'type', 'parentPath', 'parentFolderId', 'modifiedAt'],
 55→  searchOptions: {
 56→    fuzzy: 0.2,
 57→    prefix: true,
 58→    boost: { name: 1 },
 59→  },
 60→};
 61→
 62→// ---------------------------------------------------------------------------
 63→// IndexedDB constants
 64→// ---------------------------------------------------------------------------
 65→
 66→const IDB_NAME = 'cipherbox-search';
 67→const IDB_VERSION = 1;
 68→const IDB_STORE = 'index';
 69→const IDB_KEY = 'encrypted-index';
 70→
 71→// ---------------------------------------------------------------------------
 72→// HKDF constants
 73→// ---------------------------------------------------------------------------
 74→
 75→const HKDF_INFO = 'cipherbox-search-index-v1';
 76→
 77→// ---------------------------------------------------------------------------
 78→// IndexedDB helpers (follows pattern from device/identity.ts)
 79→// ---------------------------------------------------------------------------
 80→
 81→function openSearchDB(): Promise<IDBDatabase> {
 82→  return new Promise((resolve, reject) => {
 83→    const request = indexedDB.open(IDB_NAME, IDB_VERSION);
 84→    request.onupgradeneeded = () => {
 85→      request.result.createObjectStore(IDB_STORE);
 86→    };
 87→    request.onsuccess = () => resolve(request.result);
 88→    request.onerror = () => reject(request.error);
 89→  });
 90→}
 91→
 92→// ---------------------------------------------------------------------------
 93→// SearchIndexService
 94→// ---------------------------------------------------------------------------
 95→
 96→export class SearchIndexService {
 97→  private miniSearch: MiniSearch<SearchDocument>;
 98→  private indexVersion: number = 0;
 99→
100→  constructor() {
101→    this.miniSearch = new MiniSearch<SearchDocument>(MINISEARCH_OPTIONS);
102→  }
103→
104→  /**
105→   * Build the full index from the folder store's folder tree.
106→   * Walks all loaded FolderNodes and indexes their children (files and folders).
107→   *
108→   * @param folders - Record<string, FolderNode> from folder store
109→   */
110→  buildFromFolderTree(folders: Record<string, FolderNode>): void {
111→    this.miniSearch.removeAll();
112→
113→    const documents: SearchDocument[] = [];
114→
115→    for (const folder of Object.values(folders)) {
116→      const parentPath = this.buildPath(folder.id, folders);
117→
118→      // Index each child (files and subfolders)
119→      for (const child of folder.children) {
120→        documents.push({
121→          id: `${folder.id}:${child.id}`,
122→          name: child.name,
123→          type: child.type === 'folder' ? 'folder' : 'file',
124→          parentPath,
125→          parentFolderId: folder.id,
126→          modifiedAt: child.modifiedAt ?? child.createdAt ?? 0,
127→        });
128→      }
129→    }
130→
131→    // Also index folders themselves (except root) as searchable items.
132→    // A folder's parent is its parentId, so it appears in search under
133→    // the parent folder's path.
134→    for (const folder of Object.values(folders)) {
135→      if (!folder.parentId) continue; // skip root
136→      const parentFolder = folders[folder.parentId];
137→      if (!parentFolder) continue;
138→
139→      const parentPath = this.buildPath(folder.parentId, folders);
140→
141→      // Use the folder's own id with a "self:" prefix to avoid collision
142→      // with the same folder appearing as a child entry
143→      documents.push({
144→        id: `${folder.parentId}:${folder.id}`,
145→        name: folder.name,
146→        type: 'folder',
147→        parentPath,
148→        parentFolderId: folder.parentId,
149→        modifiedAt: 0, // folders don't have a top-level modifiedAt
150→      });
151→    }
152→
153→    // Deduplicate: children already include subfolder entries from parent.
154→    // The folder-self entries above may overlap with child entries.
155→    // Use a Map to keep only one document per id.
156→    const deduped = new Map<string, SearchDocument>();
157→    for (const doc of documents) {
158→      if (!deduped.has(doc.id)) {
159→        deduped.set(doc.id, doc);
160→      }
161→    }
162→
163→    this.miniSearch.addAll(Array.from(deduped.values()));
164→    this.indexVersion++;
165→  }
166→
167→  /**
168→   * Search the index with fuzzy matching.
169→   *
170→   * @param query - user's search string
171→   * @returns Array of SearchResult sorted by relevance score (descending)
172→   */
173→  search(query: string): SearchResult[] {
174→    if (!query.trim()) return [];
175→
176→    const results = this.miniSearch.search(query);
177→
178→    return results.map((result) => ({
179→      id: result.id as string,
180→      name: result.name as string,
181→      type: result.type as 'file' | 'folder',
182→      parentPath: result.parentPath as string,
183→      parentFolderId: result.parentFolderId as string,
184→      modifiedAt: result.modifiedAt as number,
185→      score: result.score,
186→      match: result.match,
187→    }));
188→  }
189→
190→  /**
191→   * Persist the current index to IndexedDB, encrypted with a key derived
192→   * from the user's vault private key via HKDF.
193→   *
194→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
195→   */
196→  async persistEncrypted(userPrivateKey: Uint8Array): Promise<void> {
197→    try {
198→      const searchKey = await this.deriveSearchKey(userPrivateKey);
199→      const serialized = JSON.stringify(this.miniSearch.toJSON());
200→      const plaintext = new TextEncoder().encode(serialized);
201→
202→      const iv = crypto.getRandomValues(new Uint8Array(12));
203→      const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, searchKey, plaintext);
204→
205→      const db = await openSearchDB();
206→      const tx = db.transaction(IDB_STORE, 'readwrite');
207→      const store = tx.objectStore(IDB_STORE);
208→
209→      // Store as number[] for cross-browser IndexedDB compatibility
210→      store.put(
211→        {
212→          iv: Array.from(iv),
213→          data: Array.from(new Uint8Array(ciphertext)),
214→        },
215→        IDB_KEY
216→      );
217→
218→      await new Promise<void>((resolve, reject) => {
219→        tx.oncomplete = () => resolve();
220→        tx.onerror = () => reject(tx.error);
221→      });
222→    } catch (err) {
223→      console.warn('[SearchIndex] Failed to persist encrypted index:', err);
224→    }
225→  }
226→
227→  /**
228→   * Load the index from IndexedDB and decrypt.
229→   *
230→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
231→   * @returns true if index was loaded successfully, false if not found or decryption failed
232→   */
233→  async loadEncrypted(userPrivateKey: Uint8Array): Promise<boolean> {
234→    try {
235→      const db = await openSearchDB();
236→      const tx = db.transaction(IDB_STORE, 'readonly');
237→      const store = tx.objectStore(IDB_STORE);
238→
239→      const stored = await new Promise<{
240→        iv: number[];
241→        data: number[];
242→      } | null>((resolve, reject) => {
243→        const request = store.get(IDB_KEY);
244→        request.onsuccess = () => resolve(request.result ?? null);
245→        request.onerror = () => reject(request.error);
246→      });
247→
248→      if (!stored || !stored.iv || !stored.data) return false;
249→
250→      const searchKey = await this.deriveSearchKey(userPrivateKey);
251→      const iv = new Uint8Array(stored.iv);
252→      const ciphertext = new Uint8Array(stored.data);
253→
254→      const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, searchKey, ciphertext);
255→
256→      const serialized = new TextDecoder().decode(plaintext);
257→      const json = JSON.parse(serialized);
258→
259→      this.miniSearch = MiniSearch.loadJSON(JSON.stringify(json), MINISEARCH_OPTIONS);
260→      return true;
261→    } catch (err) {
262→      console.warn('[SearchIndex] Failed to load encrypted index:', err);
263→      return false;
264→    }
265→  }
266→
267→  /**
268→   * Clear the in-memory index and remove the encrypted entry from IndexedDB.
269→   * Call on logout.
270→   */
271→  async clear(): Promise<void> {
272→    this.miniSearch.removeAll();
273→
274→    try {
275→      const db = await openSearchDB();
276→      const tx = db.transaction(IDB_STORE, 'readwrite');
277→      const store = tx.objectStore(IDB_STORE);
278→      store.delete(IDB_KEY);
279→
280→      await new Promise<void>((resolve, reject) => {
281→        tx.oncomplete = () => resolve();
282→        tx.onerror = () => reject(tx.error);
283→      });
284→    } catch (err) {
285→      console.warn('[SearchIndex] Failed to clear IndexedDB entry:', err);
286→    }
287→  }
288→
289→  /** Returns whether the index has any documents */
290→  get isEmpty(): boolean {
291→    return this.miniSearch.documentCount === 0;
292→  }
293→
294→  /** Returns the number of indexed documents */
295→  get size(): number {
296→    return this.miniSearch.documentCount;
297→  }
298→
299→  /** Current index version (increments on each rebuild) */
300→  get version(): number {
301→    return this.indexVersion;
302→  }
303→
304→  // -------------------------------------------------------------------------
305→  // Private helpers
306→  // -------------------------------------------------------------------------
307→
308→  /**
309→   * Build the breadcrumb path for a folder by walking up the parent chain.
310→   */
311→  private buildPath(folderId: string, folders: Record<string, FolderNode>): string {
312→    const parts: string[] = [];
313→    let currentId: string | null = folderId;
314→    while (currentId) {
315→      const node: FolderNode | undefined = folders[currentId];
316→      if (!node) break;
317→      parts.unshift(node.name);
318→      currentId = node.parentId;
319→    }
320→    return parts.join(' / ');
321→  }
322→
323→  /**
324→   * Derive a dedicated AES-256-GCM key from the user's vault private key
325→   * using HKDF with domain-separated info string.
326→   */
327→  private async deriveSearchKey(userPrivateKey: Uint8Array): Promise<CryptoKey> {
328→    const baseKey = await crypto.subtle.importKey(
329→      'raw',
330→      userPrivateKey as BufferSource,
331→      'HKDF',
332→      false,
333→      ['deriveKey']
334→    );
335→
336→    return crypto.subtle.deriveKey(
337→      {
338→        name: 'HKDF',
339→        hash: 'SHA-256',
340→        salt: new Uint8Array(0),
341→        info: new TextEncoder().encode(HKDF_INFO),
342→      },
343→      baseKey,
344→      { name: 'AES-GCM', length: 256 },
345→      false,
346→      ['encrypt', 'decrypt']
347→    );
348→  }
349→}
350→
351→// ---------------------------------------------------------------------------
352→// Singleton instance
353→// ---------------------------------------------------------------------------
354→
355→export const searchIndexService = new SearchIndexService();
356→

