 6→  const [error, setError] = useState<string | null>(null);
 7→
 8→  const deleteSingle = useCallback(async (cid: string, sizeBytes: number): Promise<void> => {
 9→    setIsDeleting(true);
10→    setError(null);
11→
12→    try {
13→      await deleteFile(cid, sizeBytes);
14→    } catch (err) {
15→      const message = (err as Error).message || 'Delete failed';
16→      setError(message);
17→      throw err;
18→    } finally {
19→      setIsDeleting(false);
20→    }
21→  }, []);
22→
23→  const deleteMultiple = useCallback(
24→    async (
25→      files: Array<{ cid: string; size: number }>
26→    ): Promise<{ succeeded: string[]; failed: string[] }> => {
27→      setIsDeleting(true);
28→      setError(null);
29→
30→      try {
31→        const result = await deleteFiles(files);
32→        if (result.failed.length > 0) {
33→          setError(`Failed to delete ${result.failed.length} file(s)`);
34→        }
35→        return result;
36→      } finally {
37→        setIsDeleting(false);
38→      }
39→    },
40→    []
41→  );
42→
43→  return {
44→    isDeleting,
45→    error,
46→    deleteFile: deleteSingle,
47→    deleteFiles: deleteMultiple,
48→    clearError: () => setError(null),
49→  };
50→}
