 1→/**
 2→ * @cipherbox/crypto - Folder Metadata Types
 3→ *
 4→ * Type definitions for encrypted folder metadata stored in IPNS records.
 5→ * v2 schema with per-file IPNS pointers (FilePointer children).
 6→ */
 7→
 8→import type { FilePointer } from '../file/types';
 9→
10→/**
11→ * Decrypted folder metadata structure (v2).
12→ * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
13→ * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
14→ */
15→export type FolderMetadata = {
16→  /** Schema version */
17→  version: 'v2';
18→  /** Folders and file pointers in this folder */
19→  children: FolderChild[];
20→};
21→
22→/**
23→ * A child entry can be either a folder or a file pointer.
24→ */
25→export type FolderChild = FolderEntry | FilePointer;
26→
27→/**
28→ * Subfolder entry within folder metadata.
29→ * Contains ECIES-wrapped keys for accessing the subfolder.
30→ */
31→export type FolderEntry = {
32→  type: 'folder';
33→  /** UUID for internal reference */
34→  id: string;
35→  /** Folder name (plaintext, since whole metadata is encrypted) */
36→  name: string;
37→  /** IPNS name for this subfolder (k51... format) */
38→  ipnsName: string;
39→  /** Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing */
40→  ipnsPrivateKeyEncrypted: string;
41→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata */
42→  folderKeyEncrypted: string;
43→  /** Creation timestamp (Unix ms) */
44→  createdAt: number;
45→  /** Last modification timestamp (Unix ms) */
46→  modifiedAt: number;
47→};
48→
49→/**
50→ * Encrypted folder metadata for storage/transmission.
51→ * This is what gets uploaded to IPFS and referenced by IPNS.
52→ */
53→export type EncryptedFolderMetadata = {
54→  /** Hex-encoded 12-byte IV for AES-GCM */
55→  iv: string;
56→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
57→  data: string;
58→};
59→

 1→/**
 2→ * @cipherbox/crypto - Per-File Metadata Types
 3→ *
 4→ * Type definitions for per-file IPNS metadata records.
 5→ * Each file gets its own IPNS record containing encrypted metadata,
 6→ * while the parent folder only stores a slim FilePointer reference.
 7→ */
 8→
 9→/** A single past version of a file. Stores full crypto context for independent decryption. */
10→export type VersionEntry = {
11→  /** IPFS CID of the encrypted file content for this version */
12→  cid: string;
13→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting this version */
14→  fileKeyEncrypted: string;
15→  /** Hex-encoded IV used for this version's encryption */
16→  fileIv: string;
17→  /** Original file size in bytes (before encryption) */
18→  size: number;
19→  /** When this version was created (Unix ms) -- i.e., when it became a "past" version */
20→  timestamp: number;
21→  /** Encryption mode used for this version */
22→  encryptionMode: 'GCM' | 'CTR';
23→};
24→
25→/**
26→ * Decrypted per-file metadata structure.
27→ * Stored as an encrypted blob in the file's own IPNS record.
28→ * Encrypted with the parent folder's folderKey (NOT the file's own key).
29→ */
30→export type FileMetadata = {
31→  /** Schema version */
32→  version: 'v1';
33→  /** IPFS CID of the encrypted file content */
34→  cid: string;
35→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting file */
36→  fileKeyEncrypted: string;
37→  /** Hex-encoded IV used for file encryption */
38→  fileIv: string;
39→  /** Original file size in bytes (before encryption) */
40→  size: number;
41→  /** MIME type of the original file */
42→  mimeType: string;
43→  /** Encryption mode (optional for backward compat; defaults to 'GCM') */
44→  encryptionMode?: 'GCM' | 'CTR';
45→  /** Creation timestamp (Unix ms) */
46→  createdAt: number;
47→  /** Last modification timestamp (Unix ms) */
48→  modifiedAt: number;
49→  /** Past versions of this file (newest first). Omitted if no versions exist. */
50→  versions?: VersionEntry[];
51→};
52→
53→/**
54→ * Slim file reference stored in v2 folder metadata.
55→ * Points to a file's own IPNS record instead of embedding all file data inline.
56→ */
57→export type FilePointer = {
58→  type: 'file';
59→  /** UUID for internal reference */
60→  id: string;
61→  /** File name (plaintext, since folder metadata is encrypted) */
62→  name: string;
63→  /** IPNS name of the file's own metadata record */
64→  fileMetaIpnsName: string;
65→  /** Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
66→   *  Present for files created after the random-key migration. Absent for legacy files
67→   *  whose IPNS key is derived deterministically via HKDF. */
68→  ipnsPrivateKeyEncrypted?: string;
69→  /** Creation timestamp (Unix ms) */
70→  createdAt: number;
71→  /** Last modification timestamp (Unix ms) */
72→  modifiedAt: number;
73→};
74→
75→/**
76→ * Encrypted file metadata for storage/transmission.
77→ * Same format as EncryptedFolderMetadata (hex IV + base64 ciphertext).
78→ */
79→export type EncryptedFileMetadata = {
80→  /** Hex-encoded 12-byte IV for AES-GCM */
81→  iv: string;
82→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
83→  data: string;
84→};
