 19→/**
 20→ * React hook for folder CRUD operations (create, rename, move, delete).
 21→ *
 22→ * Returns loading/error state and operation callbacks.
 23→ */
 24→export function useFolderMutations() {
 25→  const [state, setState] = useState<FolderOperationState>({
 26→    isLoading: false,
 27→    error: null,
 28→  });
 29→
 30→  /**
 31→   * Create a new folder.
 32→   *
 33→   * @param name - Folder name
 34→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 35→   * @returns Created folder entry
 36→   * @throws Error if depth limit exceeded or creation fails
 37→   */
 38→  const handleCreate = useCallback(
 39→    async (name: string, parentId: string | null): Promise<FolderEntry> => {
 40→      setState({ isLoading: true, error: null });
 41→      try {
 42→        const folders = useFolderStore.getState().folders;
 43→        const vault = useVaultStore.getState();
 44→        const auth = useAuthStore.getState();
 45→
 46→        // Validate depth limit before creating (FOLD-03)
 47→        const parentDepth = folderService.getDepth(parentId, folders);
 48→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 49→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 50→        }
 51→
 52→        // Get user's ECIES keypair for vault cryptographic operations (public + private keys stored in memory after login)
 53→        // The public key is used here for key wrapping; the private key remains client-side for decryption operations.
 54→        if (!auth.vaultKeypair) {
 55→          throw new Error('No ECIES keypair available - please log in again');
 56→        }
 57→        const userPublicKey = auth.vaultKeypair.publicKey;
 58→
 59→        // Create the folder (generates keys, wraps with user public key, TEE-encrypts IPNS key)
 60→        const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
 61→          await folderService.createFolder({
 62→            parentFolderId: parentId,
 63→            name,
 64→            userPublicKey,
 65→            folders,
 66→          });
 67→
 68→        // Get parent folder state
 69→        const parentFolder =
 70→          parentId && folders[parentId] ? folders[parentId] : getRootFolderState(vault, folders);
 71→
 72→        if (!parentFolder) {
 73→          throw new Error('Parent folder not found or vault not initialized');
 74→        }
 75→
 76→        // Update parent folder metadata and publish IPNS (with conflict retry)
 77→        const performParentUpdate = async () => {
 78→          const freshState = useFolderStore.getState();
 79→          const freshParent =
 80→            parentId && freshState.folders[parentId]
 81→              ? freshState.folders[parentId]
 82→              : getRootFolderState(useVaultStore.getState(), freshState.folders);
 83→          if (!freshParent) throw new Error('Parent folder not found');
 84→          const freshChildren = [...freshParent.children, folder];
 85→          const { newSequenceNumber } = await folderService.updateFolderMetadata({
 86→            folderId: freshParent.id,
 87→            children: freshChildren,
 88→            folderKey: freshParent.folderKey,
 89→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
 90→            ipnsName: freshParent.ipnsName,
 91→            sequenceNumber: freshParent.sequenceNumber,
 92→          });
 93→          return { children: freshChildren, newSequenceNumber };
 94→        };
 95→
 96→        const parentResult = await withConflictRetry(performParentUpdate, () =>
 97→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
 98→        );
 99→
100→        // First publish for the new folder's own IPNS record with TEE-encrypted key
101→        // This sends encryptedIpnsPrivateKey to backend for TEE republish enrollment
102→        const { newSequenceNumber: newFolderSequence } = await folderService.updateFolderMetadata({
103→          folderId: folder.id,
104→          children: [],
105→          folderKey,
106→          ipnsPrivateKey,
107→          ipnsName: folder.ipnsName,
108→          sequenceNumber: 0n,
109→          encryptedIpnsPrivateKey,
110→          keyEpoch,
111→        });
112→
113→        // Update local state - add new folder to tree and persist sequence
114→        useFolderStore.getState().updateFolderChildren(parentFolder.id, parentResult.children);
115→        useFolderStore
116→          .getState()
117→          .updateFolderSequence(parentFolder.id, parentResult.newSequenceNumber);
118→
119→        // Also add the new folder node to the store (with its decrypted keys)
120→        const newFolderNode: FolderNode = {
121→          id: folder.id,
122→          name: folder.name,
123→          ipnsName: folder.ipnsName,
124→          parentId: parentFolder.id,
125→          children: [],
126→          isLoaded: true,
127→          isLoading: false,
128→          sequenceNumber: newFolderSequence,
129→          folderKey,
130→          ipnsPrivateKey,
131→        };
132→        useFolderStore.getState().setFolder(newFolderNode);
133→
134→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
135→        reWrapForRecipients({
136→          folderIpnsName: parentFolder.ipnsName,
137→          folders: useFolderStore.getState().folders,
138→          currentFolderId: parentFolder.id,
139→          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
140→        }).catch((err) => {
141→          console.warn('[share] Post-create subfolder re-wrapping failed:', err);
142→        });
143→
144→        setState({ isLoading: false, error: null });
145→        return folder;
146→      } catch (err) {
147→        const error = err instanceof Error ? err.message : 'Failed to create folder';
148→        setState({ isLoading: false, error });
149→        throw err;
150→      }
151→    },
152→    []
153→  );
