155→  /**
156→   * Rename a file or folder.
157→   *
158→   * @param itemId - ID of item to rename
159→   * @param itemType - 'file' or 'folder'
160→   * @param newName - New name
161→   * @param parentId - Parent folder ID
162→   */
163→  const handleRename = useCallback(
164→    async (
165→      itemId: string,
166→      itemType: 'file' | 'folder',
167→      newName: string,
168→      parentId: string
169→    ): Promise<void> => {
170→      setState({ isLoading: true, error: null });
171→      try {
172→        const getParentFolder = () => {
173→          const freshState = useFolderStore.getState();
174→          return parentId === 'root'
175→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
176→            : freshState.folders[parentId];
177→        };
178→
179→        const parentFolder = getParentFolder();
180→        if (!parentFolder) throw new Error('Parent folder not found');
181→
182→        const performRename = async (): Promise<{ newSequenceNumber: bigint }> => {
183→          const freshParent = getParentFolder();
184→          if (!freshParent) throw new Error('Parent folder not found');
185→          if (itemType === 'folder') {
186→            return await folderService.renameFolder({
187→              folderId: itemId,
188→              newName,
189→              parentFolderState: freshParent,
190→            });
191→          } else {
192→            return await folderService.renameFile({
193→              fileId: itemId,
194→              newName,
195→              parentFolderState: freshParent,
196→            });
197→          }
198→        };
199→
200→        const renameResult = await withConflictRetry(performRename, () =>
201→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
202→        );
203→
204→        if (itemType === 'folder') {
205→          // Update local folder state name
206→          useFolderStore.getState().updateFolderName(itemId, newName);
207→        }
208→
209→        // Update parent's children with new name using fresh state
210→        const freshParent = getParentFolder();
211→        if (freshParent) {
212→          const updatedChildren = freshParent.children.map((child) => {
213→            if (child.id === itemId) {
214→              return { ...child, name: newName, modifiedAt: Date.now() };
215→            }
216→            return child;
217→          });
218→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
219→        }
220→
221→        // Persist the new sequence number so subsequent operations use the correct value
222→        useFolderStore.getState().updateFolderSequence(parentId, renameResult.newSequenceNumber);
223→
224→        setState({ isLoading: false, error: null });
225→      } catch (err) {
226→        const error = err instanceof Error ? err.message : 'Failed to rename';
227→        setState({ isLoading: false, error });
228→        throw err;
229→      }
230→    },
231→    []
232→  );
233→
234→  /**
235→   * Move a file or folder to a different parent.
236→   *
237→   * @param itemId - ID of item to move
238→   * @param itemType - 'file' or 'folder'
239→   * @param sourceParentId - Current parent folder ID
240→   * @param destParentId - Destination parent folder ID
241→   */
242→  const handleMove = useCallback(
243→    async (
244→      itemId: string,
245→      itemType: 'file' | 'folder',
246→      sourceParentId: string,
247→      destParentId: string
248→    ): Promise<void> => {
249→      setState({ isLoading: true, error: null });
250→      try {
251→        const getSourceFolder = () => {
252→          const freshState = useFolderStore.getState();
253→          return sourceParentId === 'root'
254→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
255→            : freshState.folders[sourceParentId];
256→        };
257→
258→        const getDestFolder = () => {
259→          const freshState = useFolderStore.getState();
260→          return destParentId === 'root'
261→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
262→            : freshState.folders[destParentId];
263→        };
264→
265→        const sourceFolder = getSourceFolder();
266→        const destFolder = getDestFolder();
267→        if (!sourceFolder || !destFolder) {
268→          throw new Error('Source or destination folder not found');
269→        }
270→
271→        const performMove = async (): Promise<{
272→          destSequenceNumber: bigint;
273→          sourceSequenceNumber: bigint;
274→        }> => {
275→          const freshSource = getSourceFolder();
276→          const freshDest = getDestFolder();
277→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
278→          const folders = useFolderStore.getState().folders;
279→          if (itemType === 'folder') {
280→            return await folderService.moveFolder({
281→              folderId: itemId,
282→              sourceFolderState: freshSource,
283→              destFolderState: freshDest,
284→              folders,
285→            });
286→          } else {
287→            return await folderService.moveFile({
288→              fileId: itemId,
289→              sourceFolderState: freshSource,
290→              destFolderState: freshDest,
291→            });
292→          }
293→        };
294→
295→        const moveResult = await withConflictRetry(performMove, async () => {
296→          await Promise.all([
297→            resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
298→            sourceFolder.id !== destFolder.id
299→              ? resyncFolder(destFolder.ipnsName, destFolder.id)
300→              : Promise.resolve(),
301→          ]);
302→        });
303→
304→        // Save the moved item BEFORE updating source children (otherwise it's already gone)
305→        const freshSourceBeforeUpdate = getSourceFolder();
306→        const movedItem = freshSourceBeforeUpdate?.children.find((c) => c.id === itemId);
307→
308→        if (itemType === 'folder') {
309→          // Update the moved folder's parentId in local state
310→          const freshFolders = useFolderStore.getState().folders;
311→          const movedFolder = freshFolders[itemId];
312→          if (movedFolder) {
313→            useFolderStore.getState().setFolder({
314→              ...movedFolder,
315→              parentId: destParentId,
316→            });
317→          }
318→        }
319→
320→        // Update source folder's children (remove item)
321→        if (freshSourceBeforeUpdate) {
322→          const updatedSourceChildren = freshSourceBeforeUpdate.children.filter(
323→            (c) => c.id !== itemId
324→          );
325→          useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
326→        }
327→
328→        // Update dest folder's children (add item)
329→        const freshDest = getDestFolder();
330→        if (movedItem && freshDest) {
331→          const updatedDestChildren = [
332→            ...freshDest.children,
333→            { ...movedItem, modifiedAt: Date.now() },
334→          ];
335→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
336→        }
337→
338→        // Persist the new sequence numbers so subsequent operations use the correct values
339→        useFolderStore.getState().updateFolderSequence(destParentId, moveResult.destSequenceNumber);
340→        useFolderStore
341→          .getState()
342→          .updateFolderSequence(sourceParentId, moveResult.sourceSequenceNumber);
343→
344→        setState({ isLoading: false, error: null });
345→      } catch (err) {
346→        const error = err instanceof Error ? err.message : 'Failed to move';
347→        setState({ isLoading: false, error });
348→        throw err;
349→      }
350→    },
351→    []
352→  );
353→
354→  /**
355→   * Move multiple files/folders to a destination in a single batch.
356→   *
357→   * Uses add-before-remove pattern. Publishes IPNS once for the destination
358→   * and once for the source (2 total), regardless of how many items are moved.
359→   *
360→   * @param items - Array of { id, type } to move
361→   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
362→   * @param destParentId - Destination parent folder ID
363→   */
364→  const handleMoveItems = useCallback(
365→    async (
366→      items: Array<{ id: string; type: 'file' | 'folder' }>,
367→      sourceParentId: string,
368→      destParentId: string
369→    ): Promise<void> => {
370→      setState({ isLoading: true, error: null });
371→      try {
372→        const getSourceFolder = () => {
373→          const freshState = useFolderStore.getState();
374→          return sourceParentId === 'root'
375→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
376→            : freshState.folders[sourceParentId];
377→        };
378→        const getDestFolder = () => {
379→          const freshState = useFolderStore.getState();
380→          return destParentId === 'root'
381→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
382→            : freshState.folders[destParentId];
383→        };
384→
385→        const sourceFolder = getSourceFolder();
386→        const destFolder = getDestFolder();
387→
388→        if (!sourceFolder || !destFolder) {
389→          throw new Error('Source or destination folder not found');
390→        }
391→
392→        const itemIds = new Set(items.map((i) => i.id));
393→        const now = Date.now();
394→
395→        // Validate batch move preconditions against current folder state.
396→        // Must be called before each attempt (initial + retry after resync)
397→        // because concurrent changes may introduce name collisions or depth violations.
398→        const validateBatchMove = () => {
399→          const currentSource = getSourceFolder();
400→          const currentDest = getDestFolder();
401→          if (!currentSource || !currentDest) {
402→            throw new Error('Source or destination folder not found');
403→          }
404→
405→          const currentMovedChildren = currentSource.children.filter((c) => itemIds.has(c.id));
406→          if (currentMovedChildren.length !== itemIds.size) {
407→            throw new Error(
408→              'One or more selected items no longer exist. Please refresh and retry.'
409→            );
410→          }
411→          const batchNames = new Set<string>();
412→          for (const child of currentMovedChildren) {
413→            // Intra-batch duplicate name check
414→            if (batchNames.has(child.name)) {
415→              throw new Error(`Multiple selected items share the name "${child.name}"`);
416→            }
417→            batchNames.add(child.name);
418→
419→            // Name collision check against destination
420→            const nameExists = currentDest.children.some((c) => c.name === child.name);
421→            if (nameExists) {
422→              throw new Error(`An item named "${child.name}" already exists in the destination`);
423→            }
424→
425→            if (child.type === 'folder') {
426→              // Prevent moving folder into itself or descendant
427→              const folders = useFolderStore.getState().folders;
428→              if (folderService.isDescendantOf(currentDest.id, child.id, folders)) {
429→                throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
430→              }
431→
432→              // Depth limit check
433→              const destDepth = folderService.getDepth(currentDest.id, folders);
434→              const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
435→              if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
436→                throw new Error(
437→                  `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
438→                );
439→              }
440→            }
441→          }
442→        };
443→
444→        validateBatchMove();
445→
446→        const performBatchMove = async (): Promise<{
447→          destSeq: bigint;
448→          sourceSeq: bigint;
449→          destChildren: FolderNode['children'];
450→          sourceChildren: FolderNode['children'];
451→        }> => {
452→          const freshSource = getSourceFolder();
453→          const freshDest = getDestFolder();
454→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
455→
456→          // Rebuild moved children from fresh source state
457→          const freshMoved = freshSource.children.filter((c) => itemIds.has(c.id));
458→          if (freshMoved.length !== itemIds.size) {
459→            throw new Error(
460→              'One or more selected items no longer exist. Please refresh and retry.'
461→            );
462→          }
463→
464→          // ADD all to destination FIRST (add-before-remove pattern)
465→          const destChildren = [
466→            ...freshDest.children,
467→            ...freshMoved.map((c) => ({ ...c, modifiedAt: now })),
468→          ];
469→
470→          const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
471→            folderId: freshDest.id,
472→            children: destChildren,
473→            folderKey: freshDest.folderKey,
474→            ipnsPrivateKey: freshDest.ipnsPrivateKey,
475→            ipnsName: freshDest.ipnsName,
476→            sequenceNumber: freshDest.sequenceNumber,
477→          });
478→
479→          // REMOVE all from source AFTER destination confirmed
480→          const sourceChildren = freshSource.children.filter((c) => !itemIds.has(c.id));
481→
482→          const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
483→            folderId: freshSource.id,
484→            children: sourceChildren,
485→            folderKey: freshSource.folderKey,
486→            ipnsPrivateKey: freshSource.ipnsPrivateKey,
487→            ipnsName: freshSource.ipnsName,
488→            // Re-read sequence in case source === dest parent was updated above
489→            sequenceNumber: freshSource.id === freshDest.id ? destSeq : freshSource.sequenceNumber,
490→          });
491→
492→          return { destSeq, sourceSeq, destChildren, sourceChildren };
493→        };
494→
495→        const result = await withConflictRetry(
496→          performBatchMove,
497→          async () => {
498→            await Promise.all([
499→              resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
500→              sourceFolder.id !== destFolder.id
501→                ? resyncFolder(destFolder.ipnsName, destFolder.id)
502→                : Promise.resolve(),
503→            ]);
504→          },
505→          validateBatchMove
506→        );
507→
508→        // Update local state
509→        const store = useFolderStore.getState();
510→        store.updateFolderChildren(sourceParentId, result.sourceChildren);
511→        store.updateFolderChildren(destParentId, result.destChildren);
512→        store.updateFolderSequence(destParentId, result.destSeq);
513→        store.updateFolderSequence(sourceParentId, result.sourceSeq);
514→
515→        for (const item of items) {
516→          if (item.type === 'folder') {
517→            const movedFolder = useFolderStore.getState().folders[item.id];
518→            if (movedFolder) {
519→              store.setFolder({ ...movedFolder, parentId: destParentId });
520→            }
521→          }
522→        }
523→
524→        setState({ isLoading: false, error: null });
525→      } catch (err) {
526→        const error = err instanceof Error ? err.message : 'Failed to move items';
527→        setState({ isLoading: false, error });
528→        throw err;
529→      }
530→    },
531→    []
532→  );
533→
534→  /**
535→   * Delete a file or folder.
536→   *
537→   * @param itemId - ID of item to delete
538→   * @param itemType - 'file' or 'folder'
539→   * @param parentId - Parent folder ID
540→   */
541→  const handleDelete = useCallback(
542→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
543→      setState({ isLoading: true, error: null });
544→      try {
545→        const getParentFolder = () => {
546→          const freshState = useFolderStore.getState();
547→          return parentId === 'root'
548→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
549→            : freshState.folders[parentId];
550→        };
551→
552→        const parentFolder = getParentFolder();
553→        if (!parentFolder) throw new Error('Parent folder not found');
554→
555→        const performDelete = async (): Promise<{
556→          newSequenceNumber: bigint;
557→          orphanedIpnsNames: string[];
558→        }> => {
559→          const freshParent = getParentFolder();
560→          if (!freshParent) throw new Error('Parent folder not found');
561→          if (itemType === 'folder') {
562→            const folders = useFolderStore.getState().folders;
563→            const { fileIpnsNames, newSequenceNumber } = await folderService.deleteFolder({
564→              folderId: itemId,
565→              parentFolderState: freshParent,
566→              getFolderState: (id) => folders[id],
567→            });
568→            return { newSequenceNumber, orphanedIpnsNames: fileIpnsNames };
569→          } else {
570→            const { fileMetaIpnsName, newSequenceNumber } =
571→              await folderService.deleteFileFromFolder({
572→                fileId: itemId,
573→                parentFolderState: freshParent,
574→              });
575→            return {
576→              newSequenceNumber,
577→              orphanedIpnsNames: fileMetaIpnsName ? [fileMetaIpnsName] : [],
578→            };
579→          }
580→        };
581→
582→        const deleteResult = await withConflictRetry(performDelete, () =>
583→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
584→        );
585→
586→        if (itemType === 'folder') {
587→          // Remove folder and all loaded descendants from local state
588→          const store = useFolderStore.getState();
589→          const removeRecursive = (folderId: string) => {
590→            const node = store.folders[folderId];
591→            if (node) {
592→              for (const child of node.children) {
593→                if (child.type === 'folder') removeRecursive(child.id);
594→              }
595→            }
596→            store.removeFolder(folderId);
597→          };
598→          removeRecursive(itemId);
599→        }
600→
601→        // Update parent's children (remove item) using fresh state
602→        const freshParent = getParentFolder();
603→        if (freshParent) {
604→          const updatedChildren = freshParent.children.filter((c) => c.id !== itemId);
605→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
606→        }
607→
608→        // Persist the new sequence number so subsequent operations use the correct value
609→        useFolderStore.getState().updateFolderSequence(parentId, deleteResult.newSequenceNumber);
610→
611→        // Fire-and-forget: resolve orphaned file metadata IPNS names and unpin their CIDs
612→        for (const ipnsName of deleteResult.orphanedIpnsNames) {
613→          resolveIpnsRecord(ipnsName)
614→            .then((resolved) => {
615→              if (!resolved?.cid) return;
616→              return unpinFromIpfs(resolved.cid).catch(() => {});
617→            })
618→            .catch(() => {});
619→        }
620→
621→        setState({ isLoading: false, error: null });
622→      } catch (err) {
623→        const error = err instanceof Error ? err.message : 'Failed to delete';
624→        setState({ isLoading: false, error });
625→        throw err;
626→      }
627→    },
628→    []
629→  );
630→
631→  /**
632→   * Delete multiple files/folders in a single IPNS publish.
633→   *
634→   * Removes all items from parent's children array, collects CIDs to unpin,
635→   * then publishes metadata and IPNS once for the entire batch.
636→   *
637→   * @param items - Array of { id, type } to delete
638→   * @param parentId - Parent folder ID (all items must share the same parent)
639→   */
640→  const handleDeleteItems = useCallback(
641→    async (
642→      items: Array<{ id: string; type: 'file' | 'folder' }>,
643→      parentId: string
644→    ): Promise<void> => {
645→      setState({ isLoading: true, error: null });
646→      try {
647→        const getParentFolder = () => {
648→          const freshState = useFolderStore.getState();
649→          return parentId === 'root'
650→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
651→            : freshState.folders[parentId];
652→        };
653→
654→        const parentFolder = getParentFolder();
655→        if (!parentFolder) throw new Error('Parent folder not found');
656→
657→        const itemIds = new Set(items.map((i) => i.id));
658→
659→        // Collect nested folder IDs to remove from store
660→        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
661→        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
662→        const folderIdsToRemove: string[] = [];
663→
664→        const collectFolderIds = (folderId: string) => {
665→          folderIdsToRemove.push(folderId);
666→          const folders = useFolderStore.getState().folders;
667→          const folder = folders[folderId];
668→          if (!folder) return;
669→          for (const child of folder.children) {
670→            if (child.type === 'folder') {
671→              collectFolderIds(child.id);
672→            }
673→          }
674→        };
675→
676→        for (const item of items) {
677→          if (item.type === 'folder') {
678→            collectFolderIds(item.id);
679→          }
680→        }
681→
682→        const performBatchDelete = async (): Promise<{
683→          updatedChildren: typeof parentFolder.children;
684→          newSequenceNumber: bigint;
685→        }> => {
686→          const freshParent = getParentFolder();
687→          if (!freshParent) throw new Error('Parent folder not found');
688→
689→          // Remove all items from parent's children in one pass
690→          const updatedChildren = freshParent.children.filter((c) => !itemIds.has(c.id));
691→
692→          // Single IPNS publish for the entire batch
693→          const { newSequenceNumber } = await folderService.updateFolderMetadata({
694→            folderId: freshParent.id,
695→            children: updatedChildren,
696→            folderKey: freshParent.folderKey,
697→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
698→            ipnsName: freshParent.ipnsName,
699→            sequenceNumber: freshParent.sequenceNumber,
700→          });
701→
702→          return { updatedChildren, newSequenceNumber };
703→        };
704→
705→        const { updatedChildren, newSequenceNumber } = await withConflictRetry(
706→          performBatchDelete,
707→          () => resyncFolder(parentFolder.ipnsName, parentFolder.id)
708→        );
709→
710→        // Update local state -- remove all nested folders from store
711→        const store = useFolderStore.getState();
712→        store.updateFolderChildren(parentId, updatedChildren);
713→        store.updateFolderSequence(parentId, newSequenceNumber);
714→        for (const folderId of folderIdsToRemove) {
715→          store.removeFolder(folderId);
716→        }
717→
718→        setState({ isLoading: false, error: null });
719→      } catch (err) {
720→        const error = err instanceof Error ? err.message : 'Failed to delete items';
721→        setState({ isLoading: false, error });
722→        throw err;
723→      }
724→    },
725→    []
726→  );
727→
728→  return {
729→    ...state,
730→    createFolder: handleCreate,
731→    renameItem: handleRename,
732→    moveItem: handleMove,
733→    moveItems: handleMoveItems,
734→    deleteItem: handleDelete,
735→    deleteItems: handleDeleteItems,
736→  };
737→}
