 1→import { Modal } from '../ui/Modal';
 2→import '../../styles/dialogs.css';
 3→
 4→type ConfirmDialogProps = {
 5→  /** Whether the dialog is open */
 6→  open: boolean;
 7→  /** Callback when dialog is closed (cancel or backdrop click) */
 8→  onClose: () => void;
 9→  /** Callback when action is confirmed */
10→  onConfirm: () => void;
11→  /** Dialog title */
12→  title: string;
13→  /** Dialog message/body */
14→  message: string;
15→  /** Confirm button label */
16→  confirmLabel?: string;
17→  /** Whether the action is destructive (styles confirm button as danger) */
18→  isDestructive?: boolean;
19→  /** Loading state - disables buttons */
20→  isLoading?: boolean;
21→};
22→
23→/**
24→ * Confirmation dialog for destructive actions.
25→ *
26→ * Used for confirming file/folder deletion.
27→ * Shows title, message, and Cancel/Confirm buttons.
28→ *
29→ * @example
30→ * ```tsx
31→ * function DeleteButton() {
32→ *   const [isOpen, setIsOpen] = useState(false);
33→ *
34→ *   return (
35→ *     <>
36→ *       <button onClick={() => setIsOpen(true)}>Delete</button>
37→ *       <ConfirmDialog
38→ *         open={isOpen}
39→ *         onClose={() => setIsOpen(false)}
40→ *         onConfirm={() => { deleteItem(); setIsOpen(false); }}
41→ *         title="Delete File?"
42→ *         message="Are you sure you want to delete 'document.pdf'? This cannot be undone."
43→ *         confirmLabel="Delete"
44→ *         isDestructive
45→ *       />
46→ *     </>
47→ *   );
48→ * }
49→ * ```
50→ */
51→export function ConfirmDialog({
52→  open,
53→  onClose,
54→  onConfirm,
55→  title,
56→  message,
57→  confirmLabel = 'Delete',
58→  isDestructive = true,
59→  isLoading = false,
60→}: ConfirmDialogProps) {
61→  const handleConfirm = () => {
62→    if (!isLoading) {
63→      onConfirm();
64→    }
65→  };
66→
67→  const handleCancel = () => {
68→    if (!isLoading) {
69→      onClose();
70→    }
71→  };
72→
73→  return (
74→    <Modal open={open} onClose={handleCancel} title={title}>
75→      <div className="dialog-content">
76→        <p className="dialog-message">{message}</p>
77→        <div className="dialog-actions">
78→          <button
79→            type="button"
80→            className="dialog-button dialog-button--secondary"
81→            onClick={handleCancel}
82→            disabled={isLoading}
83→          >
84→            Cancel
85→          </button>
86→          <button
87→            type="button"
88→            className={`dialog-button ${isDestructive ? 'dialog-button--destructive' : 'dialog-button--primary'}`}
89→            onClick={handleConfirm}
90→            disabled={isLoading}
91→          >
92→            {isLoading ? 'Deleting...' : confirmLabel}
93→          </button>
94→        </div>
95→      </div>
96→    </Modal>
97→  );
98→}
