  1→import axios, { AxiosProgressEvent, CancelToken } from 'axios';
  2→import { useAuthStore } from '../../stores/auth.store';
  3→
  4→const BASE_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';
  5→
  6→export type AddResponse = { cid: string; size: number; recorded: boolean };
  7→
  8→export type DownloadProgressCallback = (loaded: number, total: number) => void;
  9→
 10→/**
 11→ * Upload encrypted file to IPFS via backend relay.
 12→ * Uses axios directly for upload progress tracking (CancelToken not available in apiClient).
 13→ */
 14→export async function addToIpfs(
 15→  encryptedFile: Blob,
 16→  onProgress?: (percent: number) => void,
 17→  cancelToken?: CancelToken
 18→): Promise<AddResponse> {
 19→  const { accessToken } = useAuthStore.getState();
 20→
 21→  const formData = new FormData();
 22→  formData.append('file', encryptedFile);
 23→
 24→  const response = await axios.post<AddResponse>(`${BASE_URL}/ipfs/upload`, formData, {
 25→    headers: { Authorization: `Bearer ${accessToken}` },
 26→    onUploadProgress: (event: AxiosProgressEvent) => {
 27→      if (event.total && onProgress) {
 28→        const percent = Math.round((event.loaded * 100) / event.total);
 29→        onProgress(percent);
 30→      }
 31→    },
 32→    cancelToken,
 33→  });
 34→
 35→  return response.data;
 36→}
 37→
 38→/**
 39→ * Unpin file from IPFS via backend relay.
 40→ */
 41→export async function unpinFromIpfs(cid: string): Promise<void> {
 42→  const { accessToken } = useAuthStore.getState();
 43→  await axios.post(
 44→    `${BASE_URL}/ipfs/unpin`,
 45→    { cid },
 46→    { headers: { Authorization: `Bearer ${accessToken}` } }
 47→  );
 48→}
 49→
 50→/**
 51→ * Fetch encrypted file from IPFS via the API proxy.
 52→ * Supports progress tracking for larger files.
 53→ *
 54→ * @param cid - IPFS CID of the file
 55→ * @param onProgress - Optional callback for download progress
 56→ * @returns Encrypted file content as Uint8Array
 57→ */
 58→export async function fetchFromIpfs(
 59→  cid: string,
 60→  onProgress?: DownloadProgressCallback
 61→): Promise<Uint8Array> {
 62→  const { accessToken } = useAuthStore.getState();
 63→  const response = await fetch(`${BASE_URL}/ipfs/${cid}`, {
 64→    headers: {
 65→      Authorization: `Bearer ${accessToken}`,
 66→    },
 67→  });
 68→
 69→  if (!response.ok) {
 70→    throw new Error(`Failed to fetch from IPFS: ${response.status}`);
 71→  }
 72→
 73→  // If no progress callback or no content-length, just return arrayBuffer
 74→  const contentLength = response.headers.get('Content-Length');
 75→  if (!onProgress || !contentLength) {
 76→    const buffer = await response.arrayBuffer();
 77→    return new Uint8Array(buffer);
 78→  }
 79→
 80→  // Stream with progress
 81→  const total = parseInt(contentLength, 10);
 82→  const reader = response.body?.getReader();
 83→  if (!reader) {
 84→    throw new Error('ReadableStream not supported');
 85→  }
 86→
 87→  const chunks: Uint8Array[] = [];
 88→  let loaded = 0;
 89→
 90→  while (true) {
 91→    const { done, value } = await reader.read();
 92→    if (done) break;
 93→
 94→    chunks.push(value);
 95→    loaded += value.length;
 96→    onProgress(loaded, total);
 97→  }
 98→
 99→  // Combine chunks
100→  const result = new Uint8Array(loaded);
101→  let offset = 0;
102→  for (const chunk of chunks) {
103→    result.set(chunk, offset);
104→    offset += chunk.length;
105→  }
106→
107→  return result;
108→}
